int32_t opencut_nms_jni_onload(void* java_vm, void* reserved) {
    (void)java_vm;
    (void)reserved;
    return nextai::opencut::nms::nms_jni_onload_15074(
        nextai::opencut::nms::g_nms_engine_state);
}

int32_t opencut_nms_ces_meta(int32_t command_code,
                             const char* input_arg,
                             char* out_buf,
                             size_t out_buf_capacity) {
    const std::string arg_str = (input_arg != nullptr) ? input_arg : "";
    const std::string res = nextai::opencut::nms::nms_ces_meta_entry_38a58(
        nextai::opencut::nms::g_nms_engine_state, command_code, arg_str);
    if (out_buf != nullptr && out_buf_capacity > 0U) {
        const size_t copy_len = (res.size() < (out_buf_capacity - 1U))
            ? res.size()
            : (out_buf_capacity - 1U);
        std::memcpy(out_buf, res.data(), copy_len);
        out_buf[copy_len] = '\0';
    }
    return static_cast<int32_t>(res.size());
}

int32_t opencut_nms_run_full_self_test(void) {
    using namespace nextai::opencut::nms;

    // 1. Verify all 30 XOR catalog entries via nms_xor_decrypt_14bd4
    for (const auto& item : kNmsXorCatalog) {
        const std::string dec = nms_xor_decrypt_to_string(item.ct_bytes, item.key_bytes);
        if (dec != item.expected_plain || dec.size() != item.length) {
            return -10;
        }
    }

    // 2. Verify all 19 RC4 catalog entries via nms_rc4_decrypt_1bde4 / nms_rc4_crypt_1ba38
    for (const auto& item : kNmsRc4Catalog) {
        const std::string dec = nms_rc4_decrypt_to_string(
            item.ct_bytes, item.ct_len, item.key_bytes, 4U);
        if (dec != item.expected_plain || dec.size() != item.ct_len) {
            return -20;
        }
    }

    // 3. Verify MBA pointer deobfuscation for both anchors (0x038a58 and 0x03c670)
    if (nms_mba_compute_offset(NmsMbaConstants::kAnchorMeta, NmsMbaConstants::kXorKeyMeta) !=
        NmsMbaConstants::kOffsetMeta) {
        return -30;
    }
    if (nms_mba_compute_offset(NmsMbaConstants::kAnchorProp, NmsMbaConstants::kXorKeyProp) !=
        NmsMbaConstants::kOffsetProp) {
        return -31;
    }
    for (const auto& rel : kNmsDataMbaRelocTable) {
        const uint64_t resolved = nms_mba_resolve_pointer(
            rel.rela_addend, NmsMbaConstants::kAnchorProp, NmsMbaConstants::kXorKeyProp);
        if (resolved != rel.resolved_vaddr) {
            return -32;
        }
    }

    // 4. Verify OLLVM opaque predicates (Pell mod 7, mod 19, and RC4 madd)
    if (!nms_eval_pell_mod7_predicate(340U, 509U) ||
        !nms_eval_pell_mod7_predicate(127U, 336U) ||
        !nms_eval_pell_mod7_predicate(207U, 140U)) {
        return -40;
    }
    if (!nms_eval_mod19_predicate(318U, 155U) ||
        !nms_eval_mod19_predicate(294U, 352U)) {
        return -41;
    }
    if (nms_eval_madd_predicate_1bc40(0x1D8U, 0xB9U) != NmsRc4OllvmStates::kStateExit) {
        return -42;
    }

    // 5. Verify +0xE9 shifted syscall numbers
    if (nms_unbias_syscall_number(static_cast<uint32_t>(NmsShiftedSyscall::kOpenatShifted)) != 56U ||
        nms_unbias_syscall_number(static_cast<uint32_t>(NmsShiftedSyscall::kCloseShifted)) != 57U ||
        nms_unbias_syscall_number(static_cast<uint32_t>(NmsShiftedSyscall::kReadlinkatShifted)) != 78U ||
        nms_unbias_syscall_number(static_cast<uint32_t>(NmsShiftedSyscall::kFstatShifted)) != 80U ||
        nms_unbias_syscall_number(static_cast<uint32_t>(NmsShiftedSyscall::kGettimeofdayShifted)) != 169U ||
        nms_unbias_syscall_number(static_cast<uint32_t>(NmsShiftedSyscall::kGetpidShifted)) != 172U ||
        nms_unbias_syscall_number(static_cast<uint32_t>(NmsShiftedSyscall::kGetuidShifted)) != 174U ||
        nms_unbias_syscall_number(static_cast<uint32_t>(NmsShiftedSyscall::kSysinfoShifted)) != 179U) {
        return -50;
    }

    // 6. Verify JNI_OnLoad and meta() command execution
    NmsEngineState test_state{};
    if (nms_jni_onload_15074(test_state) != 0x00010006) {
        return -60;
    }
    if (nms_ces_meta_entry_38a58(test_state, 160) != "7.1.0.0.overseas-rc.9-switch") {
        return -61;
    }
    if (nms_ces_meta_entry_38a58(test_state, 200) != "200:OK") {
        return -62;
    }

    return 0;
}

